#!/usr/bin/env node
/**
 * Antigravity PreToolUse hook: fast text/copy and CSS-fallback anti-pattern gate.
 * Structural AST rules (nested <Card>, sparkle icons, triple-tint, tertiary contrast,
 * transition-all, spring easing, uppercase, unsafe casts) run in Oxlint (packages/eolas-ui/lint).
 */

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  raw += chunk;
});
process.stdin.on('end', () => {
  try {
    main(JSON.parse(raw));
  } catch (err) {
    process.stderr.write(`[check-anti-patterns] Hook error: ${err?.message || err}\n`);
    respond({ decision: 'allow' });
  }
});

function main(input) {
  const toolCall = input.toolCall || {};
  const args = toolCall.args || {};
  const targetFile = args.Path || args.path || args.TargetFile || args.FilePath || args.filePath || '';

  if (!/\.(tsx|jsx|css|ts|js)$/i.test(targetFile)) {
    return respond({ decision: 'allow' });
  }
  if (/(?:globals|index)\.css$|tailwind\.config\.[cm]?[jt]s$/i.test(targetFile)) {
    return respond({ decision: 'allow' });
  }
  if (/\.(?:test|spec)\.[jt]sx?$/i.test(targetFile) || /AntiPatternAuditBench\.tsx$/i.test(targetFile)) {
    return respond({ decision: 'allow' });
  }

  const content = extractContent(toolCall.name, args);
  if (!content) {
    return respond({ decision: 'allow' });
  }

  const violations = scan(content, targetFile);
  if (violations.length > 0) {
    return respond({ decision: 'deny', reason: buildReason(violations) });
  }
  return respond({ decision: 'allow' });
}

function extractContent(toolName, args) {
  if (toolName === 'write_file') return args.Content || args.content || '';
  if (toolName === 'edit_file') return args.Replacement || args.newString || '';
  if (toolName === 'write_to_file') return args.CodeContent || args.content || '';
  if (toolName === 'replace_file_content') return args.ReplacementContent || args.newString || '';
  if (toolName === 'multi_replace_file_content') {
    const chunks = args.ReplacementChunks || [];
    return chunks.map((c) => c.ReplacementContent || c.newString || '').join('\n');
  }
  return '';
}

function hasMatchingBacktick(code, startIdx) {
  for (let j = startIdx; j < code.length; j++) {
    if (code[j] === '\\') {
      j += 1;
      continue;
    }
    if (code[j] === '`') return true;
  }
  return false;
}

function stripComments(code) {
  let out = '';
  let quote = null;
  for (let i = 0; i < code.length; i++) {
    const ch = code[i];
    const next = code[i + 1];
    if (quote) {
      out += ch;
      if (ch === '\\' && i + 1 < code.length) {
        out += next;
        i += 1;
      } else if (ch === quote || ((quote === "'" || quote === '"') && (ch === '\n' || ch === '\r'))) {
        quote = null;
      }
      continue;
    }
    if (ch === '/' && next === '/') {
      while (i + 1 < code.length && code[i + 1] !== '\n') i += 1;
      continue;
    }
    if (ch === '/' && next === '*') {
      const closeIdx = code.indexOf('*/', i + 2);
      if (closeIdx !== -1) {
        out += code.slice(i, closeIdx + 2).replace(/[^\n\r]/g, ' ');
        i = closeIdx + 1;
        continue;
      }
    }
    if (ch === '"') {
      quote = '"';
    } else if (ch === '`' && hasMatchingBacktick(code, i + 1)) {
      quote = '`';
    } else if (ch === "'" && (i === 0 || !/[A-Za-z0-9]/.test(code[i - 1]))) {
      quote = "'";
    }
    out += ch;
  }
  return out;
}

const STUB_RE =
  /\/\/\s*(?:TODO:?\s*implement|\.\.\.\s*rest of|handle other cases|insert logic here)|\/\*\s*\.\.\.\s*\*\/|\{\/\*\s*\.\.\.\s*rest of[^*]*\*\/\}/i;
const EMOJI_RE = /\p{Emoji_Presentation}|\p{Extended_Pictographic}\uFE0F/u;
const AI_BUZZWORDS = 'delve|tapestry|unleash|elevate|spearhead|testament|enclave|telemetric|apparatus';
const PROP_JARGON = 'committed to|unconstrained|hydrated|synchronized|telemetry|matrix|repository';
const UI_PROP_NAMES = '(?:label|title|description|placeholder|heading|alt|aria-label|emptyText|helperText)';

const PROP_BUZZWORD_RE = new RegExp(`\\b${UI_PROP_NAMES}\\s*=\\s*["'][^"']*?\\b(?:${AI_BUZZWORDS})\\b`, 'i');
const PROP_JARGON_RE = new RegExp(`\\b${UI_PROP_NAMES}\\s*=\\s*["'][^"']*?\\b(?:${PROP_JARGON})\\b`, 'i');

function scan(content, targetFile) {
  const violations = [];
  const isJsx = /\.(tsx|jsx)$/i.test(targetFile);
  const isCss = /\.css$/i.test(targetFile);
  const stripped = stripComments(content);

  if (STUB_RE.test(content)) {
    violations.push('Found placeholder / truncation comment (e.g. "// TODO: implement", "// ... rest of"). Write complete runnable code.');
  }

  if (isJsx) {
    if (EMOJI_RE.test(stripped)) {
      violations.push('Found a decorative emoji character. Anti-patterns rule bans emojis in UI copy — use Material Symbols via <Icon>.');
    }
    if (PROP_BUZZWORD_RE.test(stripped)) {
      violations.push('Found banned AI cliché vocabulary ("delve", "tapestry", "unleash", "elevate", "enclave", "apparatus", etc.) in UI copy. Write in plain everyday English.');
    }
    if (PROP_JARGON_RE.test(stripped)) {
      violations.push('Found dev/database/CSS jargon in UI copy ("committed to", "unconstrained", "synchronized", "telemetry", "matrix", "repository"). Describe user outcomes in plain English.');
    }
  }

  if (isCss) {
    if (/text-transform\s*:\s*uppercase\b/i.test(stripped)) {
      violations.push('Found `text-transform: uppercase` in CSS. DESIGN.md bans all-caps styling.');
    }
    if (/transition(?:-property)?\s*:\s*all\b/i.test(stripped)) {
      violations.push('Found `transition: all` / `transition-property: all` in CSS. Declare explicit targeted properties.');
    }
    if (/--ease-spring\b/.test(stripped)) {
      violations.push('Found `--ease-spring` in CSS outside globals.css. Standard UI chrome must use `--ease-standard`.');
    }
  }

  return violations;
}

function buildReason(violations) {
  return `Design & anti-pattern gate blocked this change:\n${violations.map((m) => `- ${m}`).join('\n')}`;
}

function respond(obj) {
  process.stdout.write(JSON.stringify(obj));
}

#!/usr/bin/env node
/**
 * Antigravity PreToolUse hook: fires before a NEW UI component file is written.
 * Catches likely duplicate/synonym primitives anywhere in src/ and new components
 * placed directly under top-level components/ outside ui/, blocks/, or playground/demos/.
 */

import fs from 'node:fs';
import path from 'node:path';

const DEFAULT_PRIMITIVE_DIRS = [
  'src/components/ui',
  'components/ui',
  'src/primitives',
  'src/components/primitives',
];

const DEFAULT_BLOCK_DIRS = [
  'src/components/blocks',
  'components/blocks',
];

const PLAYGROUND_DIRS = [
  'src/components/playground',
  'components/playground',
  'src/components/demos',
  'components/demos',
];

const PRIMITIVE_SYNONYMS = {
  modal: ['dialog', 'alert-dialog', 'drawer'],
  popup: ['popover', 'dialog', 'tooltip'],
  dropdown: ['menu', 'select', 'combobox'],
  'dropdown-menu': ['menu', 'select', 'combobox'],
  listbox: ['select', 'combobox', 'autocomplete'],
  textbox: ['input', 'textarea', 'field'],
  textfield: ['input', 'textarea', 'field'],
  'text-field': ['input', 'textarea', 'field'],
  loader: ['spinner', 'skeleton', 'progress'],
  loading: ['spinner', 'skeleton', 'progress'],
  snackbar: ['toast'],
  notification: ['toast', 'inline-alert', 'notification-badge'],
  banner: ['inline-alert'],
  alert: ['inline-alert', 'alert-dialog'],
  btn: ['button', 'button-group'],
  pill: ['badge', 'chip'],
  tag: ['badge', 'chip'],
  divider: ['separator'],
  collapse: ['collapsible', 'accordion'],
  expander: ['collapsible', 'accordion'],
  'toggle-button': ['toggle', 'toggle-group'],
  segmented: ['toggle-group', 'tabs'],
  'segmented-control': ['toggle-group', 'tabs'],
  datepicker: ['calendar'],
  'date-picker': ['calendar'],
  'combo-box': ['combobox'],
  typeahead: ['autocomplete', 'combobox'],
  'search-input': ['input-group', 'autocomplete'],
  'file-upload': ['attachment'],
  'side-panel': ['drawer', 'sheet', 'sidebar'],
  'slide-over': ['drawer', 'sheet', 'sidebar'],
};

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  raw += chunk;
});
process.stdin.on('end', () => {
  try {
    main(JSON.parse(raw));
  } catch (err) {
    process.stderr.write(`[check-primitive-inventory] Hook error: ${err?.message || err}\n`);
    respond({ decision: 'allow' });
  }
});

function stripJsonCommentsAndTrailingCommas(text) {
  let out = '';
  let inString = false;
  let quote = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    const next = text[i + 1];
    if (inString) {
      out += ch;
      if (ch === '\\' && i + 1 < text.length) {
        out += next;
        i += 1;
      } else if (ch === quote) {
        inString = false;
      }
      continue;
    }
    if (ch === '"' || ch === "'") {
      inString = true;
      quote = ch;
      out += ch;
      continue;
    }
    if (ch === '/' && next === '/') {
      while (i + 1 < text.length && text[i + 1] !== '\n') i += 1;
      continue;
    }
    if (ch === '/' && next === '*') {
      const closeIdx = text.indexOf('*/', i + 2);
      if (closeIdx !== -1) {
        i = closeIdx + 1;
        continue;
      }
    }
    out += ch;
  }
  return out.replace(/,\s*([}\]])/g, '$1');
}

function loadTsconfigPaths(workspaceRoot) {
  const tsconfigPath = path.join(workspaceRoot, 'tsconfig.json');
  if (!fs.existsSync(tsconfigPath)) return null;
  try {
    const raw = fs.readFileSync(tsconfigPath, 'utf8');
    const parsed = JSON.parse(stripJsonCommentsAndTrailingCommas(raw));
    const paths = parsed?.compilerOptions?.paths;
    return paths && typeof paths === 'object' ? paths : null;
  } catch {
    return null;
  }
}

function resolveFromTsconfigPaths(rawAlias, tsconfigPaths) {
  if (!tsconfigPaths) return null;
  for (const [pattern, targets] of Object.entries(tsconfigPaths)) {
    if (!Array.isArray(targets) || targets.length === 0) continue;
    const firstTarget = targets[0];
    if (typeof firstTarget !== 'string') continue;

    if (pattern.endsWith('/*') && firstTarget.endsWith('/*')) {
      const prefix = pattern.slice(0, -1);
      const targetPrefix = firstTarget.slice(0, -1).replace(/^\.\//, '');
      if (rawAlias.startsWith(prefix)) {
        return `${targetPrefix}${rawAlias.slice(prefix.length)}`.replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
      }
      if (rawAlias === prefix.slice(0, -1)) {
        return targetPrefix.replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
      }
    } else if (pattern === rawAlias) {
      return firstTarget.replace(/^\.\//, '').replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
    }
  }
  return null;
}

function resolveAliasDir(rawAlias, workspaceRoot, hasSrc, tsconfigPaths = null) {
  if (!rawAlias || typeof rawAlias !== 'string') return null;
  const tsMapped = resolveFromTsconfigPaths(rawAlias, tsconfigPaths);
  if (tsMapped) return tsMapped;
  if (rawAlias.startsWith('@/')) {
    const stripped = rawAlias.slice(2).replace(/^\/+|\/+$/g, '');
    return hasSrc && !stripped.startsWith('src/') ? `src/${stripped}` : stripped;
  }
  if (rawAlias.startsWith('~/')) {
    return rawAlias.slice(2).replace(/^\/+|\/+$/g, '');
  }
  return rawAlias.replace(/\\/g, '/').replace(/^\/+|\/+$/g, '');
}

function getConfiguredDirs(workspaceRoot) {
  const hasSrc = fs.existsSync(path.join(workspaceRoot, 'src'));
  const tsconfigPaths = loadTsconfigPaths(workspaceRoot);
  const primitiveDirs = [...DEFAULT_PRIMITIVE_DIRS];
  const blockDirs = [...DEFAULT_BLOCK_DIRS];

  const configPath = path.join(workspaceRoot, 'components.json');
  if (fs.existsSync(configPath)) {
    try {
      const cfg = JSON.parse(fs.readFileSync(configPath, 'utf8'));
      const uiDir = resolveAliasDir(cfg?.aliases?.ui, workspaceRoot, hasSrc, tsconfigPaths);
      if (uiDir) {
        primitiveDirs.unshift(uiDir);
      }
      const compDir = resolveAliasDir(cfg?.aliases?.components, workspaceRoot, hasSrc, tsconfigPaths);
      if (compDir) {
        if (!cfg?.aliases?.ui) {
          primitiveDirs.unshift(`${compDir}/ui`);
        }
        blockDirs.unshift(`${compDir}/blocks`);
      }
    } catch {
      // Ignore malformed components.json
    }
  }

  return {
    primitiveDirs: [...new Set(primitiveDirs)],
    blockDirs: [...new Set(blockDirs)],
  };
}

function toKebabCase(str) {
  return str
    .replace(/([A-Z]+)([A-Z][a-z])/g, '$1-$2')
    .replace(/([a-z0-9])([A-Z])/g, '$1-$2')
    .replace(/[_\s]+/g, '-')
    .toLowerCase();
}

function main(input) {
  const toolCall = input.toolCall || {};
  const args = toolCall.args || {};
  const targetFile = args.Path || args.path || args.TargetFile || args.FilePath || args.filePath || '';

  if (!/\.(tsx|jsx)$/i.test(targetFile) || /\.(?:test|spec)\.[jt]sx?$/i.test(targetFile)) {
    return respond({ decision: 'allow' });
  }

  const fallbackCwd = path.basename(process.cwd()) === '.agents' ? path.resolve(process.cwd(), '..') : process.cwd();
  const workspaceRoot = (input.workspacePaths && input.workspacePaths[0]) || input.cwd || fallbackCwd;

  const isWindowsDriveAbs = /^[a-zA-Z]:[\\/]/.test(targetFile);
  const absoluteTarget =
    isWindowsDriveAbs || (process.platform !== 'win32' && path.isAbsolute(targetFile))
      ? targetFile
      : path.resolve(workspaceRoot, targetFile.replace(/^\/+/, ''));

  // Editing an existing file is fine — only gate brand-new files.
  if (fs.existsSync(absoluteTarget)) {
    return respond({ decision: 'allow' });
  }

  const computedRel = path.relative(workspaceRoot, absoluteTarget).replace(/\\/g, '/');
  const relPath =
    computedRel && !computedRel.startsWith('..') && !path.isAbsolute(computedRel)
      ? computedRel
      : targetFile.replace(/\\/g, '/').replace(/^\/+/, '');
  const relLower = relPath.toLowerCase();

  const { primitiveDirs, blockDirs } = getConfiguredDirs(workspaceRoot);
  const inventory = buildComponentInventory(workspaceRoot, primitiveDirs);
  const blockInventory = buildComponentInventory(workspaceRoot, blockDirs);
  if (!inventory.dir && !blockInventory.dir) {
    return respond({ decision: 'allow' });
  }

  const existingSet = new Set([
    ...inventory.names.map((n) => n.toLowerCase()),
    ...blockInventory.names.map((n) => n.toLowerCase()),
  ]);
  const uiSet = new Set(inventory.names.map((n) => n.toLowerCase()));
  const blockSet = new Set(blockInventory.names.map((n) => n.toLowerCase()));
  const baseName = path.basename(relPath).replace(/\.(tsx|jsx)$/i, '');
  const kebabName = toKebabCase(baseName);
  const strippedKebab = kebabName.replace(/^(?:custom|base|my|ui|app)-/, '');

  const isExcludedFromDuplicateCheck = /(?:^|\/)(?:blocks|playground|demos)\//i.test(relLower);
  const isInComponentScope = /^(?:src\/|(?:components|features|views|ui|primitives)\/)/i.test(relLower);

  // 1. Duplicate / synonym primitive & block check across src/ (including src/components/ui/, features/, views/)
  if (isInComponentScope && !isExcludedFromDuplicateCheck) {
    const matches = new Set();
    for (const candidate of [kebabName, strippedKebab]) {
      if (existingSet.has(candidate)) {
        matches.add(candidate);
      }
      const synonyms = PRIMITIVE_SYNONYMS[candidate];
      if (synonyms) {
        for (const syn of synonyms) {
          if (existingSet.has(syn)) matches.add(syn);
        }
      }
    }

    if (matches.size > 0) {
      const matchedList = [...matches];
      const matchedDirs = [];
      if (inventory.dir && matchedList.some((m) => uiSet.has(m))) matchedDirs.push(inventory.dir);
      if (blockInventory.dir && matchedList.some((m) => blockSet.has(m))) matchedDirs.push(blockInventory.dir);
      const locationLabel = matchedDirs.join(' / ') || inventory.dir || blockInventory.dir;
      return respond({
        decision: 'force_ask',
        reason:
          `Primitive-check gate requires confirmation:\n` +
          `New component "${targetFile}" appears to overlap with existing component(s) in ${locationLabel}: ${matchedList.join(', ')}.\n` +
          `Rule: Reuse or extend the existing component (${matchedList.join(', ')}) instead of creating a duplicate — see .agents/rules/component-library.md.`,
      });
    }
  }

  // 2. Top-level components/ layer check (excludes feature-local src/features/*/components/)
  const isTopLevelComponents = /^(?:src\/)?components\//i.test(relLower);
  if (isTopLevelComponents) {
    const allowedDirsLower = [...primitiveDirs, ...blockDirs, ...PLAYGROUND_DIRS].map((d) =>
      `${d.replace(/\\/g, '/').replace(/^\/+|\/+$/g, '').toLowerCase()}/`
    );
    const isInsideAllowedDir = allowedDirsLower.some((dirPrefix) => relLower.startsWith(dirPrefix));

    if (!isInsideAllowedDir) {
      const primaryInventory = inventory.dir ? inventory : blockInventory;
      const sample = primaryInventory.names.slice(0, 12).join(', ');
      const extraCount = primaryInventory.names.length > 12 ? ` (+${primaryInventory.names.length - 12} more)` : '';
      return respond({
        decision: 'force_ask',
        reason:
          `Primitive-check gate requires confirmation:\n` +
          `New component "${targetFile}" sits directly under top-level components/ outside ui/, blocks/, or playground/.\n` +
          `Place reusable primitives in ${primaryInventory.dir} (${primaryInventory.names.length} existing: ${sample}${extraCount}), composite assemblies in src/components/blocks/, or domain components in src/features/ or src/views/.`,
      });
    }
  }

  return respond({ decision: 'allow' });
}

function collectComponentNames(rootDir, currentDir = rootDir, names = new Set()) {
  let entries;
  try {
    entries = fs.readdirSync(currentDir, { withFileTypes: true });
  } catch {
    return names;
  }
  for (const entry of entries) {
    if (entry.name.startsWith('.') || entry.name === 'node_modules') continue;
    const fullPath = path.join(currentDir, entry.name);
    if (entry.isDirectory()) {
      collectComponentNames(rootDir, fullPath, names);
    } else if (entry.isFile() && /\.(?:tsx|jsx|ts|js)$/i.test(entry.name)) {
      if (/\.(?:test|spec|stories)\.[jt]sx?$/i.test(entry.name)) continue;
      const stem = entry.name.replace(/\.(?:tsx|jsx|ts|js)$/i, '');
      if (stem.toLowerCase() === 'index') {
        if (currentDir !== rootDir) {
          names.add(toKebabCase(path.basename(currentDir)));
        }
      } else {
        names.add(toKebabCase(stem));
      }
    }
  }
  return names;
}

function buildComponentInventory(workspaceRoot, candidateDirs) {
  for (const dir of candidateDirs) {
    const absoluteDir = path.join(workspaceRoot, dir);
    if (fs.existsSync(absoluteDir) && fs.statSync(absoluteDir).isDirectory()) {
      const names = [...collectComponentNames(absoluteDir)].sort();
      return { dir, names };
    }
  }
  return { dir: null, names: [] };
}

function respond(obj) {
  process.stdout.write(JSON.stringify(obj));
}

#!/usr/bin/env node
/**
 * Antigravity PreToolUse hook: scans code and config about to be written
 * for hardcoded secrets, private keys, and high-entropy API tokens BEFORE
 * the file is written.
 *
 * Hard-blocks (decision: "deny") live production API keys and private keys.
 * Surfaces ambiguous matches as "force_ask".
 */

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  raw += chunk;
});
process.stdin.on('end', () => {
  try {
    main(JSON.parse(raw));
  } catch (err) {
    process.stderr.write(`[check-secrets] Hook error: ${err?.message || err}\n`);
    respond({
      decision: 'force_ask',
      reason: 'Secret-scanning hook encountered an unexpected error and could not verify this write. Review for secrets before proceeding.',
    });
  }
});

function main(input) {
  const toolCall = input.toolCall || {};
  const args = toolCall.args || {};
  const targetFile = args.Path || args.path || args.TargetFile || args.FilePath || args.filePath || '';

  // Exclude example files and lockfiles from strict secret checks
  if (/\.env\.example$|package-lock\.json$|yarn\.lock$|pnpm-lock\.yaml$/i.test(targetFile)) {
    return respond({ decision: 'allow' });
  }

  const content = extractContent(toolCall.name, args);
  if (!content) {
    return respond({ decision: 'allow' });
  }

  const isMarkdown = /\.md$/i.test(targetFile);
  const violations = scanForSecrets(content, { isMarkdown });
  if (violations.length > 0) {
    const decision = violations.some((v) => v.severity === 'deny')
      ? 'deny'
      : violations.some((v) => v.severity === 'force_ask')
        ? 'force_ask'
        : 'ask';
    return respond({ decision, reason: buildReason(violations) });
  }
  return respond({ decision: 'allow' });
}

function extractContent(toolName, args) {
  if (toolName === 'write_file') return args.Content || args.content || '';
  if (toolName === 'edit_file') return args.Replacement || args.newString || '';
  if (toolName === 'write_to_file') return args.CodeContent || args.content || '';
  if (toolName === 'replace_file_content') return args.ReplacementContent || args.newString || '';
  if (toolName === 'multi_replace_file_content') {
    const chunks = args.ReplacementChunks || [];
    return chunks.map((c) => c.ReplacementContent || c.newString || '').join('\n');
  }
  return '';
}

function scanForSecrets(content, { isMarkdown = false } = {}) {
  const violations = [];

  // Ignore only unambiguous placeholder templates — never bare substrings like "test" inside random key entropy.
  const isExplicitPlaceholder = (str) =>
    /(.)\1{5,}/.test(str) ||
    /<[^>]+>/.test(str) ||
    /(?:^|[_-])(?:mock|dummy|example|placeholder|changeme|fake|sample|replace[_-]?me|your[_-]?api|your[_-]?key|your[_-]?token|your[_-]?pass(?:word)?)(?:[_-]|$)/i.test(str) ||
    /(?:^|[^a-zA-Z0-9])(?:test|mock|dummy|fake|example)[_-](?:key|token|secret|password)(?:$|[^a-zA-Z0-9])/i.test(str);

  const DB_PLACEHOLDER_PW_RE =
    /^(?:password|passwd|secret|changeme|example|placeholder|your[_-]?pass(?:word)?|postgres|mysql|redis|mongo|admin|root|test|demo|local|dev|xxx+)$/i;

  const isPlausibleGenericSecret = (val) =>
    !val.includes('${') &&
    !/^[a-z]+(?:-[a-z]+)+$/.test(val) &&
    !/^[a-z]+(?:_[a-z]+)+$/.test(val) &&
    !/^[a-z]+(?:\.[a-z]+)+$/.test(val) &&
    !/^(?:https?:\/\/|\/)/i.test(val) &&
    (/[0-9]/.test(val) || (/[A-Z]/.test(val) && /[a-z]/.test(val)));

  const findLiveMatch = (globalRegex, groupIdx = 0, extraFilter = null) => {
    for (const match of content.matchAll(globalRegex)) {
      const candidate = match[groupIdx] ?? match[0];
      if (!candidate) continue;
      if (extraFilter && !extraFilter(candidate, match)) continue;
      if (!isExplicitPlaceholder(candidate)) return match;
    }
    return null;
  };

  // 1. Google / Firebase / Gemini API Key
  if (findLiveMatch(/AIza[0-9A-Za-z-_]{35}/g)) {
    violations.push({
      severity: 'deny',
      message:
        'Detected hardcoded Google/Firebase/Gemini API Key (starts with "AIza..."). Move this secret to environment variables (.env.local) or use secret manager.',
    });
  }

  // 2. OpenAI / Anthropic / Model API Key (anchored to avoid kebab-case false positives like "task-...")
  if (
    findLiveMatch(
      /(?:^|[^a-zA-Z0-9_-])(sk-(?:proj-|ant-|live-|svcacct-)[A-Za-z0-9_-]{20,}|sk-[A-Za-z0-9]{20,}T3BlbkFJ[A-Za-z0-9]{20,}|sk-[A-Za-z0-9]{32,})(?=$|[^a-zA-Z0-9_-])/g,
      1,
      (val) => /[A-Z0-9]/.test(val.slice(3))
    )
  ) {
    violations.push({
      severity: 'deny',
      message:
        'Detected hardcoded API Secret Key (starts with "sk-..."). Never commit live API tokens into source code.',
    });
  }

  // 3. GitHub Personal Access / OAuth / User-to-Server / App Tokens
  if (findLiveMatch(/(?:ghp|gho|ghu|ghs|ghr)_[a-zA-Z0-9]{36}|github_pat_[a-zA-Z0-9]{22}_[a-zA-Z0-9]{59}/g)) {
    violations.push({
      severity: 'deny',
      message: 'Detected hardcoded GitHub Token. Revoke and move to secure secret storage.',
    });
  }

  // 4. AWS Access Key ID
  if (findLiveMatch(/\bAKIA[0-9A-Z]{16}\b/g)) {
    violations.push({
      severity: 'deny',
      message: 'Detected hardcoded AWS Access Key ID. Use IAM roles or environment variables.',
    });
  }

  // 5. Private Keys (RSA / DSA / EC / OPENSSH / ENCRYPTED / PGP)
  if (/-----BEGIN (?:(?:RSA|EC|OPENSSH|DSA|ENCRYPTED|PGP) )?PRIVATE KEY(?: BLOCK)?-----/.test(content)) {
    violations.push({
      severity: 'deny',
      message: 'Detected Private Key block. Private keys must never be written to application files.',
    });
  }

  // 6. Slack API Tokens (including multi-segment xox* and xapp tokens)
  if (findLiveMatch(/\bxox[baprs]-[0-9a-zA-Z-]{10,}\b|\bxapp-\d-[A-Za-z0-9-]{10,}\b/g)) {
    violations.push({
      severity: 'deny',
      message: 'Detected hardcoded Slack Token.',
    });
  }

  // 7. Stripe Live Secret / Restricted Keys
  if (findLiveMatch(/\b[sr]k_live_[0-9a-zA-Z]{24,}\b/g)) {
    violations.push({
      severity: 'deny',
      message: 'Detected Stripe Live Secret Key. Live billing credentials must remain server-side in secure environment variables.',
    });
  }

  // 8. Signed 3-segment JSON Web Tokens (JWT)
  if (findLiveMatch(/\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}\b/g)) {
    violations.push({
      severity: 'deny',
      message: 'Detected hardcoded JWT token literal. Never commit signed bearer tokens into source files.',
    });
  }

  // 9. Database connection URIs with embedded non-placeholder passwords
  if (
    findLiveMatch(
      /(?:postgres|postgresql|mysql|mongodb(?:\+srv)?|redis|rediss):\/\/[^:\s/'"]+:([^@\s/'"]{8,})@/gi,
      1,
      (val) => !val.includes('${') && !DB_PLACEHOLDER_PW_RE.test(val)
    )
  ) {
    violations.push({
      severity: 'deny',
      message: 'Detected database connection URI with an embedded password. Move credentials to environment variables.',
    });
  }

  // 10. Generic hardcoded high-entropy credentials in JS/TS/JSON or unquoted .env (skipped in Markdown docs)
  if (!isMarkdown) {
    const genericSecretAssignment =
      findLiveMatch(
        /(?:["']?)(api_key|apiKey|secret_key|secretKey|auth_token|authToken|access_token|accessToken|private_key|privateKey|password)(?:["']?)\s*[:=]\s*(["'`])([^\s"'`\\]{32,})\2/gi,
        3,
        isPlausibleGenericSecret
      ) ||
      findLiveMatch(
        /^[ \t]*(?:export[ \t]+)?([A-Z0-9_]*(?:API_KEY|SECRET_KEY|AUTH_TOKEN|ACCESS_TOKEN|PRIVATE_KEY|PASSWORD))[ \t]*=[ \t]*([^\s#]{32,})[ \t]*(?:#.*)?$/gm,
        2,
        isPlausibleGenericSecret
      );

    if (genericSecretAssignment) {
      const matchedKeyName = genericSecretAssignment[1];
      violations.push({
        severity: 'force_ask',
        message: `Detected potential hardcoded credential assignment for "${matchedKeyName}". Confirm if this is a test dummy or real secret before writing.`,
      });
    }
  }

  return violations;
}

function buildReason(violations) {
  const lines = violations.map((v) => `- ${v.message}`);
  return `Secret-scanning gate blocked this change:\n${lines.join('\n')}`;
}

function respond(obj) {
  process.stdout.write(JSON.stringify(obj));
}

#!/usr/bin/env node
/**
 * Antigravity Stop hook: runs local Oxlint on modified/untracked source files
 * at the end of an agent turn, feeding AST diagnostics back into the loop once.
 * Safely no-ops if Oxlint / .oxlintrc.json is not installed or when continuationActive is true.
 */

import fs from 'node:fs';
import path from 'node:path';
import { spawnSync } from 'node:child_process';

const IGNORED_PREFIXES = [
  'dist/',
  'public/',
  'node_modules/',
  '.agents/',
  'packages/eolas-ui/registry/',
  'packages/eolas-ui/lint/',
  'lint/',
  'scratch/',
  'docs/',
];

let raw = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  raw += chunk;
});
process.stdin.on('end', () => {
  try {
    const input = raw.trim() ? JSON.parse(raw) : {};
    main(input);
  } catch (err) {
    process.stderr.write(`[check-oxlint-on-stop] Hook error: ${err?.message || err}\n`);
    respond({});
  }
});

function main(input) {
  if (input.continuationActive === true) {
    return respond({});
  }
  if (input.terminationReason && input.terminationReason !== 'NO_TOOL_CALL') {
    return respond({});
  }

  const fallbackCwd = path.basename(process.cwd()) === '.agents' ? path.resolve(process.cwd(), '..') : process.cwd();
  const workspaceRoot = (input.workspacePaths && input.workspacePaths[0]) || input.cwd || fallbackCwd;

  const oxlintRc = path.join(workspaceRoot, '.oxlintrc.json');
  const oxlintScript = path.join(workspaceRoot, 'node_modules', 'oxlint', 'bin', 'oxlint');
  const oxlintBin = path.join(
    workspaceRoot,
    'node_modules',
    '.bin',
    process.platform === 'win32' ? 'oxlint.cmd' : 'oxlint'
  );

  if (!fs.existsSync(oxlintRc)) {
    return respond({});
  }
  const hasScript = fs.existsSync(oxlintScript);
  const hasBin = fs.existsSync(oxlintBin);
  if (!hasScript && !hasBin) {
    return respond({});
  }

  const ignoredPrefixes = [...IGNORED_PREFIXES];
  try {
    const oxlintCfg = JSON.parse(fs.readFileSync(oxlintRc, 'utf8'));
    if (Array.isArray(oxlintCfg?.ignorePatterns)) {
      for (const pattern of oxlintCfg.ignorePatterns) {
        if (typeof pattern !== 'string') continue;
        const cleaned = pattern.replace(/^\.\//, '').replace(/\\/g, '/');
        const prefixMatch = cleaned.match(/^([^?*[\]{}]+?)(?:\/\*\*|\/\*|\/)?$/);
        if (prefixMatch && prefixMatch[1]) {
          const prefix = prefixMatch[1].endsWith('/') ? prefixMatch[1] : `${prefixMatch[1]}/`;
          if (!ignoredPrefixes.includes(prefix)) {
            ignoredPrefixes.push(prefix);
          }
        }
      }
    }
  } catch {
    // Fall back to default IGNORED_PREFIXES if .oxlintrc.json cannot be parsed
  }

  const topRes = spawnSync('git', ['rev-parse', '--show-toplevel'], {
    cwd: workspaceRoot,
    encoding: 'utf8',
    timeout: 5000,
  });

  if (topRes.error || topRes.status !== 0 || !topRes.stdout) {
    return respond({});
  }

  const gitTopLevel = safeRealpath(topRes.stdout.trim());
  const resolvedWorkspaceRoot = safeRealpath(workspaceRoot);

  const gitRes = spawnSync('git', ['status', '--porcelain', '-uall', '-z'], {
    cwd: workspaceRoot,
    encoding: 'utf8',
    timeout: 5000,
  });

  if (gitRes.error || gitRes.status !== 0 || !gitRes.stdout) {
    return respond({});
  }

  const tokens = gitRes.stdout.split('\0');
  const filesToLint = [];
  const seen = new Set();

  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (!token || token.length < 4) continue;
    const statusCode = token.slice(0, 2);
    const relRaw = token.slice(3);
    if (statusCode[0] === 'R' || statusCode[0] === 'C' || statusCode[1] === 'R' || statusCode[1] === 'C') {
      i += 1;
    }
    if (!relRaw) continue;

    const absPath = path.resolve(gitTopLevel, relRaw);
    const relToWorkspace = path.relative(resolvedWorkspaceRoot, absPath);
    if (!relToWorkspace || relToWorkspace.startsWith('..') || path.isAbsolute(relToWorkspace)) {
      continue;
    }

    const norm = relToWorkspace.replace(/\\/g, '/').replace(/^\.\//, '');
    if (!/\.(?:ts|tsx|js|jsx|mjs|cjs)$/i.test(norm)) continue;
    if (ignoredPrefixes.some((prefix) => norm.startsWith(prefix))) continue;

    if (!fs.existsSync(absPath)) continue;
    try {
      if (!fs.statSync(absPath).isFile()) continue;
    } catch {
      continue;
    }

    if (!seen.has(norm)) {
      seen.add(norm);
      filesToLint.push(norm);
    }
  }

  if (filesToLint.length === 0) {
    return respond({});
  }

  const lintRes = hasScript
    ? spawnSync(process.execPath, [oxlintScript, ...filesToLint], {
        cwd: workspaceRoot,
        encoding: 'utf8',
        timeout: 20000,
      })
    : spawnSync(oxlintBin, filesToLint, {
        cwd: workspaceRoot,
        encoding: 'utf8',
        shell: process.platform === 'win32',
        timeout: 20000,
      });

  if (lintRes.error) {
    process.stderr.write(`[check-oxlint-on-stop] Failed to run oxlint: ${lintRes.error.message}\n`);
    return respond({});
  }

  if (lintRes.status !== 0) {
    const combined = [lintRes.stdout, lintRes.stderr].filter(Boolean).join('\n').trim();
    if (/No files found to lint|Finished in \d+m?s on 0 files/i.test(combined)) {
      return respond({});
    }
    const trimmed = combined.length > 3000 ? `${combined.slice(0, 3000)}\n... (truncated)` : combined;
    return respond({
      decision: 'continue',
      reason: `Oxlint reported errors in modified files. Fix them before finishing:\n\n${trimmed}`,
    });
  }

  return respond({});
}

function safeRealpath(targetPath) {
  try {
    return fs.realpathSync(targetPath);
  } catch {
    return path.resolve(targetPath);
  }
}

function respond(obj) {
  process.stdout.write(JSON.stringify(obj));
}
